@push('scripts')@if($selected&&config('logistics.map_provider')==='leaflet_osm')<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{if(typeof L==='undefined')return;const el=document.getElementById('tracking-map');el.innerHTML='';const map=L.map(el).setView([12.8797,121.774],6);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);let marker,centered=false;const poll=async()=>{try{const response=await fetch(@js(route('logistics.tracking.feed',$selected)),{headers:{Accept:'application/json'},credentials:'same-origin'});const data=await response.json();const label=document.getElementById('live-status');if(!data.location){label.textContent='Waiting for Rider location…';return;}const point=[data.location.latitude,data.location.longitude];marker?marker.setLatLng(point):marker=L.marker(point).addTo(map).bindPopup(@js($selected->rider?->name??'Assigned Rider'));if(!centered){map.setView(point,16);centered=true;}label.textContent=data.location.source==='simulation'?'GPS Simulation — Development Only':`${data.live?'Real GPS · Live':'Real GPS · Last update'} ${new Date(data.location.recorded_at).toLocaleTimeString()}`;}catch(e){document.getElementById('live-status').textContent='Tracking temporarily unavailable';}};poll();setInterval(poll,Math.max(10000,@js(config('logistics.tracking_interval_seconds')*1000)));});</script>@endif @endpush
